const body = $input.first().json.body || {};
const entries = body.entry || [];
const eventos = [];

for (const entry of entries) {
  const entryId = entry.id || '';

  // 1. Direct Messages
  if (entry.messaging && Array.isArray(entry.messaging)) {
    for (const msg of entry.messaging) {
      if (msg.message && !msg.message.is_echo) {
        const senderId = msg.sender ? msg.sender.id : '';

        // Bloqueio de auto-mensagens (Marcão enviando para si mesmo)
        if (
          senderId === entryId || 
          senderId === '17841417712557777' || 
          senderId === '28570207812599721'
        ) {
          continue;
        }

        let isAudio = false;
        let audioUrl = null;

        if (msg.message.attachments && Array.isArray(msg.message.attachments)) {
          for (const att of msg.message.attachments) {
            if (att.type === 'audio' || att.type === 'voice' || att.type === 'file') {
              isAudio = true;
              audioUrl = att.payload ? att.payload.url : null;
            }
          }
        }

        const texto = (msg.message.text || '').trim();

        if (texto || isAudio) {
          eventos.push({
            tipo: 'direct',
            senderId: senderId,
            recipientId: msg.recipient ? msg.recipient.id : '',
            messageId: msg.message.mid || '',
            texto: texto || '[Áudio enviado pelo seguidor no Direct]',
            isAudio: isAudio,
            audioUrl: audioUrl,
            timestamp: msg.timestamp
          });
        }
      }
    }
  }

  // 2. Comentários em Posts / Reels
  if (entry.changes && Array.isArray(entry.changes)) {
    for (const change of entry.changes) {
      if (change.field === 'comments' && change.value) {
        const val = change.value;
        const from = val.from || {};
        const fromUsername = (from.username || '').toLowerCase();
        const fromId = from.id || '';

        // BLOQUEIO RIGOROSO DE AUTO-COMENTÁRIOS E LOOP INFINITO:
        // Se o comentário for feito pelo próprio Marcão, IGNORA IMEDIATAMENTE!
        if (
          fromUsername === 'marcaopersonalfitness' ||
          fromUsername.includes('marcao') ||
          fromId === entryId ||
          fromId === '17841417712557777' ||
          fromId === '28570207812599721' ||
          Boolean(from.self_ig_scoped_id)
        ) {
          continue; // Pula sem processar para não entrar em loop infinito!
        }

        if (val.text) {
          eventos.push({
            tipo: 'comentario',
            commentId: val.id,
            mediaId: val.media ? val.media.id : '',
            fromUser: from.username || '',
            fromId: fromId,
            texto: val.text.trim(),
            createdTime: val.created_time
          });
        }
      }
    }
  }
}

return eventos.map(e => ({ json: e }));

