function devePesquisarNaWeb(texto) {
  if (!texto) return false;
  let t = texto.trim().toLowerCase();
  t = t.replace(/[!?,;.]+/g, ' ').replace(/\s+/g, ' ').trim();
  const tokensCasuais = new Set([
    'ok', 'tudo', 'bem', 'bom', 'td', 'certo', 'cima', 'beleza', 'blz', 'tranquilo', 
    'como', 'vai', 'voce', 'você', 'esta', 'está', 'e', 'ai', 'aí', 'opa', 'oi', 
    'ola', 'olá', 'bom', 'dia', 'boa', 'tarde', 'noite', 'valeu', 'obrigado', 
    'obrigada', 'combinado', 'fechado', 'sim', 'ta', 'tá', 'show', 'top', 'tmj', 
    'marcao', 'marcão', 'fala', 'irmão', 'irmao', 'parceiro', 'campeão', 'campeao'
  ]);
  const palavras = t.split(' ').filter(w => w.length > 0);
  const todasSaoCasuais = palavras.length > 0 && palavras.every(w => tokensCasuais.has(w));
  if (todasSaoCasuais) return false;
  if (/^(treinei|treino pago|t[aá] pago|fui treinar|acabei o treino|hoje tem|cansei|pesando|estou com|tenho \d+|concordo|fechado)/i.test(t)) {
    return false;
  }
  const temInterrogacao = texto.includes('?');
  const termosPergunta = /\b(o que|oq|qual|quais|como|por que|pq|quanto|quantos|quem|onde|quando|pesquisa|pesquise|busca|busque|explica|explique|sabe me dizer|me tira uma d[uú]vida|d[uú]vida|voc[eê] conhece|voce conhece|indica|recomenda|vale a pena|funciona|estudo|pesquisa recente)\b/i.test(t);
  return termosPergunta || (temInterrogacao && palavras.length >= 3);
}

function detectarGenero(username, nome) {
  const u = (username || '').toLowerCase().replace(/[^a-z0-9_]/g, '');
  const n = (nome || '').toLowerCase().trim();

  const nomesFem = new Set([
    'eva', 'maria', 'ana', 'juliana', 'bruna', 'beatriz', 'camila', 'amanda', 
    'fernanda', 'patricia', 'vanessa', 'leticia', 'gabriela', 'carla', 'debora', 
    'aline', 'mariana', 'larissa', 'renata', 'luiza', 'jessica', 'monique', 
    'claudia', 'luciana', 'daniela', 'raquel', 'thais', 'sabrina', 'natalia', 
    'flavia', 'carol', 'caroline', 'isabela', 'isabella', 'elaine', 'cristina', 
    'simone', 'tatiane', 'tatiana', 'silvia', 'regina', 'valeria', 'marcia', 
    'monica', 'adriana', 'andreia', 'andressa', 'priscila', 'rosana', 
    'rose', 'paula', 'paloma', 'suelen', 'bianca', 'viviane', 'helena', 'alice', 
    'laura', 'sophia', 'sofia', 'manuela', 'valentina', 'lorena', 'livia', 'yasmin',
    'giovanna', 'rafaela', 'clara', 'barbara', 'teresa', 'terezinha', 'solange',
    'marta', 'neuza', 'neusa', 'cleide', 'fatima', 'lurdes', 'lourdes', 'sonia'
  ]);

  const marcadoresFem = ['mulher', 'menina', 'mamae', 'mae', 'garota', 'lady', 'miss', 'dra', 'nutri', 'fitgirl', 'fem', 'princesa', 'bela'];
  for (const m of marcadoresFem) {
    if (u.includes(m)) return 'f';
  }

  if (n) {
    const pNome = n.split(/\s+/)[0];
    if (nomesFem.has(pNome)) return 'f';
  }

  for (const fem of nomesFem) {
    if (u.startsWith(fem) || u.includes('_' + fem) || u.includes('.' + fem)) {
      return 'f';
    }
  }

  const nomesMasc = new Set([
    'evandro', 'carlos', 'rodrigo', 'marcos', 'marcao', 'lucas', 'pedro', 'joao', 
    'gabriel', 'matheus', 'felipe', 'guilherme', 'bruno', 'andre', 'tiago', 'diego', 
    'rafael', 'fernando', 'marcelo', 'ricardo', 'leonardo', 'gustavo', 'roberto', 
    'eduardo', 'alexandre', 'fabio', 'paulo', 'antonio', 'francisco', 'jose', 
    'luiz', 'luis', 'marcio', 'danilo', 'vitor', 'victor', 'leandro', 'filipe', 
    'caio', 'renan', 'igor', 'arthur', 'artur', 'bernardo', 'heitor', 'davi', 
    'david', 'samuel', 'miguel', 'enzo', 'theo', 'luciano', 'julio', 'cesar'
  ]);

  const marcadoresMasc = ['homem', 'moleque', 'papai', 'pai', 'garoto', 'boy', 'mr', 'maromba'];
  for (const m of marcadoresMasc) {
    if (u.includes(m)) return 'm';
  }

  if (n) {
    const pNome = n.split(/\s+/)[0];
    if (nomesMasc.has(pNome)) return 'm';
  }

  for (const masc of nomesMasc) {
    if (u.startsWith(masc) || u.includes('_' + masc) || u.includes('.' + masc)) {
      return 'm';
    }
  }

  return 'neutro';
}

