        let isAudio = false;
        let audioUrl = null;

        if (msg.message.attachments && Array.isArray(msg.message.attachments)) {
          for (const att of msg.message.attachments) {
            if (att.type === 'audio' || att.type === 'voice' || att.type === 'file') {
              isAudio = true;
