// 2. SE FOR MENSAGEM DE ÁUDIO: GERA VOZ DO MARCÃO NO ELEVENLABS E DISPACHA ÁUDIO NO DIRECT
if (isAudio) {
  try {
    const textoParaVoz = rawText.replace(/https?:\/\/\S+/g, '').replace(/[*_#]/g, '').trim();

    // Gera PCM 24kHz no ElevenLabs
    const elevenRes = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://api.elevenlabs.io/v1/text-to-speech/${elevenVoice}?output_format=pcm_24000`,
      headers: {
        'xi-api-key': elevenKey,
        'Content-Type': 'application/json'
      },
      body: {
