        model_id: 'eleven_multilingual_v2',
        voice_settings: {
          stability: 0.5,
          similarity_boost: 0.8
        }
      },
      encoding: 'arraybuffer'
    });

    const pcm = Buffer.from(elevenRes);

    // Constrói cabeçalho WAV padrão de 44 bytes compatível com a Meta
    const sampleRate = 24000;
    const numChannels = 1;
    const bitsPerSample = 16;
    const byteRate = (sampleRate * numChannels * bitsPerSample) / 8;
    const blockAlign = (numChannels * bitsPerSample) / 8;
    const dataSize = pcm.length;
    const chunkSize = 36 + dataSize;

    const header = Buffer.alloc(44);
    header.write('RIFF', 0);
    header.writeUInt32LE(chunkSize, 4);
    header.write('WAVE', 8);
    header.write('fmt ', 12);
    header.writeUInt32LE(16, 16);
    header.writeUInt16LE(1, 20); // PCM
    header.writeUInt16LE(numChannels, 22);
    header.writeUInt32LE(sampleRate, 24);
    header.writeUInt32LE(byteRate, 28);
    header.writeUInt16LE(blockAlign, 32);
    header.writeUInt16LE(bitsPerSample, 34);
    header.write('data', 36);
    header.writeUInt32LE(dataSize, 40);

    const wavBuffer = Buffer.concat([header, pcm]);
    const fileName = `marcao_audio_${Date.now()}_${Math.floor(Math.random() * 1000)}.wav`;

    // Upload para Supabase Storage
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${sbUrl}/storage/v1/object/creativos/${fileName}`,
      headers: {
        'apikey': sbKey,
        'Authorization': `Bearer ${sbKey}`,
        'Content-Type': 'audio/wav',
        'x-upsert': 'true'
      },
      body: wavBuffer
    });

    const publicAudioUrl = `${sbUrl}/storage/v1/object/public/creativos/${fileName}`;

    // Disparo do Áudio no Direct do Instagram via Meta Graph API
    const resAudio = await this.helpers.httpRequest({
      method: 'POST',
