    });
    sentResults.push({ type: 'audio', result: resAudio, url: publicAudioUrl });
  } catch (audioErr) {
    const errDetails = audioErr.response ? audioErr.response.data : audioErr.message;
    sentResults.push({ type: 'audio_error', error: audioErr.message, details: errDetails });
  }
}

// 3. Fatiamento em Balões Curtos (< 60 caracteres) para envio de Texto
const urls = [];
const textoComPlaceholders = rawText.replace(/https?:\/\/\S+/g, (match) => {
  urls.push(match);
  return `\n__URL_${urls.length - 1}__\n`;
});

const blocos = textoComPlaceholders.split(/\n+/).map(b => b.trim()).filter(b => b.length > 0);
const rawUnits = [];

for (const b of blocos) {
  if (b.startsWith('__URL_')) {
    const idx = parseInt(b.replace('__URL_', '').replace('__', ''), 10);
    if (!isNaN(idx) && urls[idx]) {
      rawUnits.push(urls[idx]);
    }
    continue;
  }

  const sents = b.split(/(?<=[.!?])\s+/).filter(s => s.trim().length > 0);
  for (const s of sents) {
    const st = s.trim();
    if (!st) continue;

    if (st.length > 60 && (st.includes(',') || st.includes(';') || st.includes(' - '))) {
      const partes = st.split(/(?<=[,;])\s+|(?<=\s-\s)/).filter(p => p.trim().length > 0);
      for (const pt of partes) {
        if (pt.trim()) rawUnits.push(pt.trim());
      }
    } else {
      rawUnits.push(st);
    }
  }
}

const finalBubbles = [];
for (const u of rawUnits) {
  if (finalBubbles.length === 0) {
    finalBubbles.push(u);
    continue;
  }
  if (u.length <= 3 && !u.startsWith('http')) {
    finalBubbles[finalBubbles.length - 1] += ' ' + u;
  } else {
    finalBubbles.push(u);
  }
}

// Delay de 1.5s entre o áudio e os balões de texto
if (isAudio) {
  await new Promise(r => setTimeout(r, 1500));
}


// REAÇÃO AUTOMÁTICA DE EMOJI NO BALÃO DO INTERLOCUTOR (SE HOUVER MESSAGE_ID)
const messageId = eventData.messageId || '';
if (messageId && recipientId) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.instagram.com/v21.0/me/messages',
      headers: {
        'Authorization': `Bearer ${igToken}`,
        'Content-Type': 'application/json'
      },
      body: {
        recipient: { id: recipientId },
        message: {
          reaction: {
            message_id: messageId,
            action: 'react',
            emoji: '🔥'
          }
        }
      },
      json: true
    });
  } catch (e) {
    // Graceful fallback se a conta Meta não tiver flag de reaction ativa
  }
}
// reacao_emoji_direct: OK

// 4. Envio sequencial de cada balão no Direct
for (let i = 0; i < finalBubbles.length; i++) {
  const bText = finalBubbles[i];
  if (!bText) continue;

  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://graph.instagram.com/v21.0/me/messages',
      headers: {
        'Authorization': `Bearer ${igToken}`,
        'Content-Type': 'application/json'
      },
      body: {
        recipient: { id: recipientId },
        message: { text: bText }
      },
      json: true
    });
    sentResults.push(res);
  } catch (err) {
    const errDetails = err.response ? err.response.data : err.message;
    sentResults.push({ error: err.message, details: errDetails });
  }

  if (i < finalBubbles.length - 1) {
    await new Promise(r => setTimeout(r, 1500));
  }
}

return [{ json: { ...item, recipientId, isAudio, finalBubbles, sentResults } }];

