} catch (e) {
  const mId = llmRaw.match(/"idioma_detectado"\s*:\s*"([a-zA-Z]+)"/);
  if (mId) idioma = mId[1].toLowerCase();

  const mPede = llmRaw.match(/"pede_explicacao_produto"\s*:\s*(true|false)/);
  if (mPede) pedeProduto = (mPede[1] === 'true');

  const mResp = llmRaw.match(/"resposta_comentario"\s*:\s*"([^"\\]*(?:\\.[^"\\]*)*)"/);
  if (mResp) {
    respostaComentario = mResp[1].replace(/\\"/g, '"').replace(/\\n/g, ' ').trim();
  }

  const mDir = llmRaw.match(/"mensagem_direct"\s*:\s*"([\s\S]+)/);
  if (mDir) {
    mensagemDirect = mDir[1].replace(/"\s*\}?[\s\S]*$/, '').replace(/\\"/g, '"').replace(/\\n/g, '\n').trim();
  }
}

// 2. DETECÇÃO ROBUSTA DE INTENÇÃO NO COMENTÁRIO (Garante que se pediu o post/link/preço/info, NUNCA é ignorado!)
const termosPedido = /\b(send|post|manda|mandar|link|preco|preço|valor|quanto|como comprar|onde compro|quero|direct|dm|inbox|info|informacoes|informações|me envia|envia|manda no direct)\b/i;
if (termosPedido.test(textoComentario)) {
  pedeProduto = true;
}

